with d as (select value r from jsonb_array_elements($q$[{"slug":"vetkoek","title":"Vetkoek with Curried Mince","cuisine":"south-african","meal_types":["lunch","snack"],"diets":["no-dairy"],"difficulty":"medium","total_minutes":140,"recipe":{"id":"vetkoek","title":"Vetkoek with Curried Mince","summary":"Golden fried bread puffs, split while hot and stuffed with gently curried beef mince.","cuisine":"south-african","diets":["no-dairy"],"mealTypes":["lunch","snack"],"difficulty":"medium","prepMinutes":100,"cookMinutes":40,"servings":6,"onePot":false,"ingredientGroups":[{"title":"Dough","items":[{"item":"plain flour","raw":"500g plain flour","quantity":500,"unit":"g","ingredientId":"plain-flour"},{"item":"instant dried yeast","raw":"2 tsp instant dried yeast","quantity":2,"unit":"tsp","ingredientId":"yeast"},{"item":"white sugar","raw":"1 tbsp white sugar","quantity":1,"unit":"tbsp","ingredientId":"sugar"},{"item":"salt","raw":"1 tsp salt","quantity":1,"unit":"tsp","ingredientId":"salt"},{"item":"lukewarm water","raw":"330ml lukewarm water","quantity":330,"unit":"ml","ingredientId":"water"},{"item":"Neutral oil","raw":"Neutral oil, for deep-frying","ingredientId":"neutral-oil","prep":"for deep-frying"}]},{"title":"Curried mince","items":[{"item":"neutral oil","raw":"1 tbsp neutral oil","quantity":1,"unit":"tbsp","ingredientId":"neutral-oil"},{"item":"brown onion","raw":"1 brown onion, diced","quantity":1,"ingredientId":"brown-onion","prep":"diced"},{"item":"garlic","raw":"2 garlic cloves, crushed","quantity":2,"unit":"clove","ingredientId":"garlic","prep":"crushed"},{"item":"curry powder","raw":"1 tbsp curry powder","quantity":1,"unit":"tbsp","ingredientId":"curry-powder"},{"item":"beef mince","raw":"500g beef mince","quantity":500,"unit":"g","ingredientId":"beef-mince"},{"item":"carrot","raw":"1 carrot, grated","quantity":1,"ingredientId":"carrot","prep":"grated"},{"item":"tomatoes","raw":"2 tomatoes, diced","quantity":2,"ingredientId":"tomato","prep":"diced"},{"item":"tomato paste","raw":"1 tbsp tomato paste","quantity":1,"unit":"tbsp","ingredientId":"tomato-paste"},{"item":"fruit chutney","raw":"1 tbsp fruit chutney","quantity":1,"unit":"tbsp","ingredientId":"chutney"},{"item":"water","raw":"125ml water","quantity":125,"unit":"ml","ingredientId":"water"},{"item":"frozen peas","raw":"100g frozen peas","quantity":100,"unit":"g","ingredientId":"frozen-peas"},{"item":"salt","raw":"1/2 tsp salt","quantity":0.5,"unit":"tsp","ingredientId":"salt"}]}],"steps":[{"text":"Mix the flour, yeast, sugar and salt. Add the water and knead for 5 to 8 minutes into a smooth, soft dough. Cover and leave somewhere warm for about 1 hour, until doubled."},{"text":"Meanwhile, make the mince. Heat the oil in a frying pan over medium heat and cook the onion for 5 minutes. Add the garlic and curry powder for 1 minute, then the mince. Turn the heat up and cook for 6 to 8 minutes, breaking it up, until browned all over."},{"text":"Add the carrot, tomatoes, tomato paste, chutney and water. Simmer for 15 minutes until thick, adding the peas for the last 3 minutes. The mince should be cooked through with no pink left (75°C). Season with the salt and keep warm."},{"text":"Knock back the dough and divide into 12 balls. Flatten each slightly and rest on a floured tray for 15 minutes."},{"text":"Heat 4cm of oil in a heavy saucepan to 170°C. Fry 3 or 4 at a time for 3 to 4 minutes a side, until deep golden and they sound hollow when tapped. Break the first one open to check the middle is cooked. Drain on paper towel."},{"text":"Split each vetkoek while warm and fill with curried mince."}],"notes":["If they brown too fast and stay doughy inside, the oil is too hot. Let it come back down to 170°C.","Never leave hot oil unattended, and let it cool completely before moving the pan.","Vetkoek are also good with butter and golden syrup, or cheese and apricot jam.","Food safety: Cook mince, sausages, meatballs and liver right through to 75°C, with no pink in the centre."],"source":"user","provenance":"ai-draft"}},{"slug":"upma","title":"Upma","cuisine":"indian","meal_types":["breakfast"],"diets":["vegetarian"],"difficulty":"easy","total_minutes":30,"recipe":{"id":"upma","title":"Upma","summary":"A South Indian breakfast of toasted semolina cooked soft with mustard seeds, curry leaves, cashews and vegetables.","cuisine":"indian","diets":["vegetarian"],"mealTypes":["breakfast"],"difficulty":"easy","prepMinutes":10,"cookMinutes":20,"servings":3,"onePot":true,"ingredientGroups":[{"items":[{"item":"semolina","raw":"180g semolina","quantity":180,"unit":"g","ingredientId":"semolina"},{"item":"ghee","raw":"2 tbsp ghee (or neutral oil)","quantity":2,"unit":"tbsp","ingredientId":"ghee","note":"or neutral oil"},{"item":"mustard seeds","raw":"1 tsp mustard seeds","quantity":1,"unit":"tsp","ingredientId":"mustard-seeds"},{"item":"cumin seeds","raw":"1 tsp cumin seeds","quantity":1,"unit":"tsp","ingredientId":"cumin-seeds"},{"item":"curry leaves","raw":"1 sprig curry leaves","quantity":1,"unit":"sprig","ingredientId":"curry-leaf"},{"item":"cashews","raw":"30g cashews","quantity":30,"unit":"g","ingredientId":"cashews"},{"item":"brown onion","raw":"1 brown onion, finely diced","quantity":1,"ingredientId":"brown-onion","prep":"finely diced"},{"item":"green chilli","raw":"1 green chilli, finely chopped","quantity":1,"ingredientId":"green-chilli","prep":"finely chopped"},{"item":"grated ginger","raw":"1 tbsp grated ginger","quantity":1,"unit":"tbsp","ingredientId":"ginger"},{"item":"carrot","raw":"1 carrot, finely diced","quantity":1,"ingredientId":"carrot","prep":"finely diced"},{"item":"frozen peas","raw":"60g frozen peas","quantity":60,"unit":"g","ingredientId":"frozen-peas"},{"item":"water","raw":"625ml water","quantity":625,"unit":"ml","ingredientId":"water"},{"item":"salt","raw":"1 tsp salt","quantity":1,"unit":"tsp","ingredientId":"salt"},{"item":"lemon","raw":"Juice of 1/2 lemon","quantity":0.5,"ingredientId":"lemon","prep":"juiced"},{"item":"coriander leaves","raw":"Handful of coriander leaves, chopped","quantity":1,"unit":"handful","ingredientId":"coriander","prep":"chopped"}]}],"steps":[{"text":"Toast the semolina in a dry frying pan over medium heat for 4 to 5 minutes, stirring, until it smells nutty but hasn't coloured. Tip onto a plate."},{"text":"Heat the ghee in a saucepan over medium heat. Add the mustard seeds and, once they pop, the cumin seeds, curry leaves and cashews. Stir for 1 minute until the cashews are golden."},{"text":"Add the onion, chilli and ginger and cook for 4 minutes until soft. Add the carrot and peas and cook for 2 minutes."},{"text":"Pour in the water, add the salt and bring to the boil. Turn the heat to low and pour in the semolina in a slow stream, stirring all the time so it doesn't lump, until the mixture is thick and soft and pulls away from the sides of the pan."},{"text":"Cover and cook for 3 minutes, then stir. It should be soft and fluffy. Stir through the lemon juice and coriander and serve hot."}],"notes":["Use the coarser semolina if your supermarket has a choice; Indian grocers sell it as rava or sooji.","Upma firms up as it cools. Loosen leftovers with a splash of hot water when reheating."],"source":"user","provenance":"ai-draft"}},{"slug":"pork-vindaloo","title":"Pork Vindaloo","cuisine":"indian","meal_types":["dinner"],"diets":["no-gluten","no-dairy"],"difficulty":"medium","total_minutes":385,"recipe":{"id":"pork-vindaloo","title":"Pork Vindaloo","summary":"Goan pork shoulder marinated in a chilli, garlic and vinegar paste, then braised until tender and tangy.","cuisine":"indian","diets":["no-gluten","no-dairy"],"mealTypes":["dinner"],"difficulty":"medium","prepMinutes":265,"cookMinutes":120,"servings":5,"onePot":false,"seasons":["autumn","winter"],"ingredientGroups":[{"title":"Paste","items":[{"item":"dried Kashmiri chillies","raw":"8 dried Kashmiri chillies, stemmed and seeded","quantity":8,"ingredientId":"dried-chilli","prep":"stemmed and seeded"},{"item":"cumin seeds","raw":"1 tsp cumin seeds","quantity":1,"unit":"tsp","ingredientId":"cumin-seeds"},{"item":"black peppercorns","raw":"1 tsp black peppercorns","quantity":1,"unit":"tsp","ingredientId":"black-pepper"},{"item":"cinnamon","raw":"1 cinnamon stick","quantity":1,"unit":"stick","ingredientId":"cinnamon-stick"},{"item":"ground cloves","raw":"1/4 tsp ground cloves","quantity":0.25,"unit":"tsp","ingredientId":"ground-cloves"},{"item":"ground turmeric","raw":"1 tsp ground turmeric","quantity":1,"unit":"tsp","ingredientId":"ground-turmeric"},{"item":"garlic","raw":"6 garlic cloves","quantity":6,"unit":"clove","ingredientId":"garlic"},{"item":"grated ginger","raw":"2 tbsp grated ginger","quantity":2,"unit":"tbsp","ingredientId":"ginger"},{"item":"white vinegar","raw":"80ml white vinegar","quantity":80,"unit":"ml","ingredientId":"white-vinegar"},{"item":"brown sugar","raw":"1 tbsp brown sugar","quantity":1,"unit":"tbsp","ingredientId":"brown-sugar"},{"item":"salt","raw":"1 tsp salt","quantity":1,"unit":"tsp","ingredientId":"salt"}]},{"title":"Curry","items":[{"item":"pork shoulder","raw":"1.2kg pork shoulder, cut into 4cm pieces","quantity":1.2,"unit":"kg","ingredientId":"pork-shoulder","prep":"cut into 4cm pieces"},{"item":"neutral oil","raw":"3 tbsp neutral oil","quantity":3,"unit":"tbsp","ingredientId":"neutral-oil"},{"item":"brown onions","raw":"2 brown onions, finely sliced","quantity":2,"ingredientId":"brown-onion","prep":"finely sliced"},{"item":"tomatoes","raw":"2 tomatoes, chopped","quantity":2,"ingredientId":"tomato","prep":"chopped"},{"item":"water","raw":"250ml water","quantity":250,"unit":"ml","ingredientId":"water"}]},{"title":"To serve","items":[{"item":"basmati rice","raw":"300g basmati rice","quantity":300,"unit":"g","ingredientId":"basmati-rice"}]}],"steps":[{"text":"Soak the chillies in just-boiled water for 15 minutes. Meanwhile, toast the cumin seeds, peppercorns and cinnamon stick in a dry pan for 1 minute until fragrant."},{"text":"Drain the chillies and blend them with the toasted spices (break up the cinnamon), the cloves, turmeric, garlic, ginger, vinegar, sugar and salt to a smooth paste."},{"text":"Rub the paste all over the pork in a bowl. Cover and refrigerate for at least 4 hours, or overnight."},{"text":"Heat the oil in a heavy pot over medium heat and cook the onions for 12 minutes, until golden. Add the pork and all its paste and fry for 5 minutes, stirring."},{"text":"Add the tomatoes and water and bring to a simmer. Cover and cook on low heat for 1 1/2 hours, stirring now and then, until the pork is very tender. Uncover and simmer for 15 minutes more to thicken."},{"text":"Meanwhile, cook the rice until tender and fluffy. Taste the curry for salt, check that the pork is tender and the sauce thick, and serve."}],"notes":["Kashmiri chillies give colour more than fire, so this is warm rather than blistering. Add 1/2 tsp cayenne pepper to the paste for a hotter vindaloo.","It improves overnight. Cool quickly, refrigerate within an hour and reheat until bubbling.","Food safety: Cook fresh pork to at least 70°C in the thickest part."],"source":"user","provenance":"ai-draft"}},{"slug":"rajma","title":"Rajma","cuisine":"indian","meal_types":["dinner","lunch"],"diets":["vegetarian","no-gluten"],"difficulty":"easy","total_minutes":50,"recipe":{"id":"rajma","title":"Rajma","summary":"Punjabi red kidney beans simmered in a thick, gently spiced onion and tomato gravy, made for rice.","cuisine":"indian","diets":["vegetarian","no-gluten"],"mealTypes":["dinner","lunch"],"difficulty":"easy","prepMinutes":10,"cookMinutes":40,"servings":4,"onePot":false,"ingredientGroups":[{"title":"Rajma","items":[{"item":"ghee","raw":"2 tbsp ghee (or neutral oil)","quantity":2,"unit":"tbsp","ingredientId":"ghee","note":"or neutral oil"},{"item":"cumin seeds","raw":"1 tsp cumin seeds","quantity":1,"unit":"tsp","ingredientId":"cumin-seeds"},{"item":"bay","raw":"1 bay leaf","quantity":1,"unit":"leaf","ingredientId":"bay-leaf"},{"item":"brown onions","raw":"2 brown onions, finely chopped","quantity":2,"ingredientId":"brown-onion","prep":"finely chopped"},{"item":"ginger garlic paste","raw":"1 tbsp ginger garlic paste","quantity":1,"unit":"tbsp","ingredientId":"ginger-garlic-paste"},{"item":"green chilli","raw":"1 green chilli, slit lengthways","quantity":1,"ingredientId":"green-chilli","prep":"slit lengthways"},{"item":"ground coriander","raw":"1 tsp ground coriander","quantity":1,"unit":"tsp","ingredientId":"ground-coriander"},{"item":"Kashmiri chilli powder","raw":"1 tsp Kashmiri chilli powder","quantity":1,"unit":"tsp","ingredientId":"kashmiri-chilli-powder"},{"item":"ground turmeric","raw":"1/2 tsp ground turmeric","quantity":0.5,"unit":"tsp","ingredientId":"ground-turmeric"},{"item":"crushed tomatoes","raw":"400g tin crushed tomatoes","quantity":400,"unit":"g","ingredientId":"tinned-tomatoes","note":"tin"},{"item":"tinned red kidney beans","raw":"800g tinned red kidney beans, drained and rinsed","quantity":800,"unit":"g","ingredientId":"kidney-beans","prep":"drained and rinsed"},{"item":"water","raw":"500ml water","quantity":500,"unit":"ml","ingredientId":"water"},{"item":"salt","raw":"1 tsp salt","quantity":1,"unit":"tsp","ingredientId":"salt"},{"item":"garam masala","raw":"1 tsp garam masala","quantity":1,"unit":"tsp","ingredientId":"garam-masala"},{"item":"dried fenugreek leaves","raw":"1 tsp dried fenugreek leaves","quantity":1,"unit":"tsp","ingredientId":"fenugreek-leaves"},{"item":"coriander leaves","raw":"Handful of coriander leaves, chopped","quantity":1,"unit":"handful","ingredientId":"coriander","prep":"chopped"}]},{"title":"To serve","items":[{"item":"basmati rice","raw":"300g basmati rice","quantity":300,"unit":"g","ingredientId":"basmati-rice"}]}],"steps":[{"text":"Heat the ghee in a saucepan over medium heat. Add the cumin seeds and bay leaf and let them sizzle for 30 seconds."},{"text":"Add the onions and cook for 12 to 15 minutes, stirring often, until deep golden. Add the ginger garlic paste and green chilli and cook for 2 minutes."},{"text":"Stir in the ground coriander, chilli powder and turmeric for 30 seconds, then add the tomatoes. Cook for 8 minutes, until thick and the oil starts to separate at the edges."},{"text":"Add the beans, water and salt. Simmer for 15 minutes, mashing a few beans against the side of the pan to thicken the gravy."},{"text":"Meanwhile, cook the rice. Crush the fenugreek leaves between your palms into the rajma, add the garam masala and simmer for 2 minutes. Scatter with coriander and serve with the rice."}],"notes":["To cook from dried beans, soak 250g overnight, then boil hard for 10 minutes and simmer until soft (about 1 hour). Raw or undercooked kidney beans are toxic, so never slow-cook them from raw.","Rajma chawal (with rice) is the classic, but it's also good with roti."],"source":"user","provenance":"ai-draft"}},{"slug":"onion-bhaji","title":"Onion Bhaji","cuisine":"indian","meal_types":["snack"],"diets":["vegetarian","vegan","no-gluten","no-dairy"],"difficulty":"easy","total_minutes":40,"recipe":{"id":"onion-bhaji","title":"Onion Bhaji","summary":"Crisp, lacy tangles of spiced onion in chickpea batter, fried golden and served with mint chutney.","cuisine":"indian","diets":["vegetarian","vegan","no-gluten","no-dairy"],"mealTypes":["snack"],"difficulty":"easy","prepMinutes":20,"cookMinutes":20,"servings":4,"onePot":false,"ingredientGroups":[{"items":[{"item":"brown onions","raw":"3 brown onions, halved and thinly sliced","quantity":3,"ingredientId":"brown-onion","prep":"halved and thinly sliced"},{"item":"salt","raw":"1 tsp salt","quantity":1,"unit":"tsp","ingredientId":"salt"},{"item":"chickpea flour","raw":"130g chickpea flour","quantity":130,"unit":"g","ingredientId":"chickpea-flour"},{"item":"rice flour","raw":"2 tbsp rice flour","quantity":2,"unit":"tbsp","ingredientId":"rice-flour"},{"item":"cumin seeds","raw":"1 tsp cumin seeds","quantity":1,"unit":"tsp","ingredientId":"cumin-seeds"},{"item":"ground turmeric","raw":"1/2 tsp ground turmeric","quantity":0.5,"unit":"tsp","ingredientId":"ground-turmeric"},{"item":"Kashmiri chilli powder","raw":"1 tsp Kashmiri chilli powder","quantity":1,"unit":"tsp","ingredientId":"kashmiri-chilli-powder"},{"item":"green chilli","raw":"1 green chilli, finely chopped","quantity":1,"ingredientId":"green-chilli","prep":"finely chopped"},{"item":"grated ginger","raw":"1 tbsp grated ginger","quantity":1,"unit":"tbsp","ingredientId":"ginger"},{"item":"coriander leaves","raw":"Handful of coriander leaves, chopped","quantity":1,"unit":"handful","ingredientId":"coriander","prep":"chopped"},{"item":"cold water","raw":"60ml cold water","quantity":60,"unit":"ml","ingredientId":"water"},{"item":"Neutral oil","raw":"Neutral oil, for deep-frying","ingredientId":"neutral-oil","prep":"for deep-frying"},{"item":"Mint chutney","raw":"Mint chutney, to serve","ingredientId":"mint-chutney","prep":"to serve"}]}],"steps":[{"text":"Toss the onions with the salt in a large bowl and leave for 10 minutes, until they soften and release some liquid."},{"text":"Add the chickpea flour, rice flour, cumin seeds, turmeric, chilli powder, green chilli, ginger and coriander. Mix with your hands, then add the water a little at a time until the onions are coated in a thick, sticky batter. You may not need it all."},{"text":"Heat 4cm of oil in a heavy saucepan to 170°C. Drop in loose spoonfuls of the mixture, 4 or 5 at a time, and fry for 4 to 5 minutes, turning, until deep golden and crisp."},{"text":"Drain on paper towel and serve hot with mint chutney."}],"notes":["Keep them loose and craggy rather than pressing them into balls; the straggly edges are the crispest part.","Never leave hot oil unattended, and let it cool completely before moving the pan."],"source":"user","provenance":"ai-draft"}},{"slug":"panang-beef-curry","title":"Panang Beef Curry","cuisine":"thai","meal_types":["dinner"],"diets":["no-gluten","no-dairy"],"difficulty":"easy","total_minutes":40,"recipe":{"id":"panang-beef-curry","title":"Panang Beef Curry","summary":"A thick, rich Thai curry of tender beef in coconut cream, sweet with peanut and fragrant with lime leaves.","cuisine":"thai","diets":["no-gluten","no-dairy"],"mealTypes":["dinner"],"difficulty":"easy","prepMinutes":15,"cookMinutes":25,"servings":4,"onePot":false,"ingredientGroups":[{"title":"Curry","items":[{"item":"coconut cream","raw":"400ml coconut cream","quantity":400,"unit":"ml","ingredientId":"coconut-cream"},{"item":"red curry paste","raw":"3 tbsp red curry paste","quantity":3,"unit":"tbsp","ingredientId":"red-curry-paste"},{"item":"smooth peanut butter","raw":"2 tbsp smooth peanut butter","quantity":2,"unit":"tbsp","ingredientId":"peanut-butter"},{"item":"grated palm sugar","raw":"1 tbsp grated palm sugar","quantity":1,"unit":"tbsp","ingredientId":"palm-sugar"},{"item":"fish sauce","raw":"1 tbsp fish sauce","quantity":1,"unit":"tbsp","ingredientId":"fish-sauce"},{"item":"beef rump steak","raw":"600g beef rump steak, thinly sliced across the grain","quantity":600,"unit":"g","ingredientId":"beef-rump","prep":"thinly sliced across the grain"},{"item":"makrut lime","raw":"4 makrut lime leaves, very finely shredded","quantity":4,"unit":"leaf","ingredientId":"makrut-lime-leaf","prep":"very finely shredded"},{"item":"long red chilli","raw":"1 long red chilli, thinly sliced","quantity":1,"ingredientId":"red-chilli","prep":"thinly sliced"},{"item":"Thai basil leaves","raw":"Handful of Thai basil leaves","quantity":1,"unit":"handful","ingredientId":"thai-basil"}]},{"title":"To serve","items":[{"item":"jasmine rice","raw":"300g jasmine rice","quantity":300,"unit":"g","ingredientId":"jasmine-rice"}]}],"steps":[{"text":"Start the rice cooking. Put half the coconut cream in a wok or wide pan over medium heat and simmer for 4 to 5 minutes, stirring, until it thickens and the oil starts to separate."},{"text":"Add the curry paste and fry for 2 minutes until fragrant. Stir in the peanut butter, palm sugar and fish sauce."},{"text":"Add the beef, the rest of the coconut cream and most of the lime leaves. Simmer gently for 4 to 5 minutes, until the beef is just cooked and the sauce is thick enough to coat it. Add a splash of water if it gets too thick."},{"text":"Taste and balance with more fish sauce or sugar. Scatter with the chilli, Thai basil and remaining lime leaves and serve with the rice."}],"notes":["If you find panang curry paste, use it instead of the red curry paste and halve the peanut butter. Red curry paste with peanut is a common stand-in.","Slice the beef more easily by putting it in the freezer for 20 minutes first.","Food safety: Steaks and roasting cuts of beef or lamb can be served pink: about 60°C in the centre is medium-rare, 70°C is well done."],"source":"user","provenance":"ai-draft"}},{"slug":"yum-woon-sen","title":"Yum Woon Sen","cuisine":"thai","meal_types":["lunch","dinner"],"diets":["no-gluten","no-dairy"],"difficulty":"easy","total_minutes":30,"recipe":{"id":"yum-woon-sen","title":"Yum Woon Sen","summary":"A Thai glass noodle salad with pork and prawns, tossed in a hot, sour and salty lime dressing.","cuisine":"thai","diets":["no-gluten","no-dairy"],"mealTypes":["lunch","dinner"],"difficulty":"easy","prepMinutes":20,"cookMinutes":10,"servings":4,"onePot":false,"seasons":["summer"],"ingredientGroups":[{"title":"Salad","items":[{"item":"glass noodles","raw":"150g glass noodles","quantity":150,"unit":"g","ingredientId":"glass-noodles"},{"item":"pork mince","raw":"250g pork mince","quantity":250,"unit":"g","ingredientId":"pork-mince"},{"item":"water","raw":"2 tbsp water","quantity":2,"unit":"tbsp","ingredientId":"water"},{"item":"raw prawns","raw":"250g raw prawns, peeled and deveined","quantity":250,"unit":"g","ingredientId":"prawn","prep":"peeled and deveined"},{"item":"red shallots","raw":"2 red shallots, thinly sliced","quantity":2,"ingredientId":"shallot","prep":"thinly sliced"},{"item":"celery","raw":"2 celery stalks, thinly sliced on an angle","quantity":2,"unit":"stalk","ingredientId":"celery","prep":"thinly sliced on an angle"},{"item":"cherry tomatoes","raw":"150g cherry tomatoes, halved","quantity":150,"unit":"g","ingredientId":"cherry-tomato","prep":"halved"},{"item":"spring onions","raw":"2 spring onions, cut into 3cm lengths","quantity":2,"ingredientId":"spring-onion","prep":"cut into 3cm lengths"},{"item":"coriander leaves","raw":"Handful of coriander leaves","quantity":1,"unit":"handful","ingredientId":"coriander"},{"item":"roasted peanuts","raw":"2 tbsp roasted peanuts, chopped","quantity":2,"unit":"tbsp","ingredientId":"peanuts","prep":"chopped"},{"item":"Lettuce leaves","raw":"Lettuce leaves, to serve","ingredientId":"lettuce","prep":"to serve"}]},{"title":"Dressing","items":[{"item":"fish sauce","raw":"3 tbsp fish sauce","quantity":3,"unit":"tbsp","ingredientId":"fish-sauce"},{"item":"limes","raw":"Juice of 3 limes","quantity":3,"ingredientId":"lime","prep":"juiced"},{"item":"white sugar","raw":"1 tbsp white sugar","quantity":1,"unit":"tbsp","ingredientId":"sugar"},{"item":"bird's eye chillies","raw":"2 bird's eye chillies, finely sliced","quantity":2,"ingredientId":"birds-eye-chilli","prep":"finely sliced"},{"item":"garlic","raw":"2 garlic cloves, finely chopped","quantity":2,"unit":"clove","ingredientId":"garlic","prep":"finely chopped"}]}],"steps":[{"text":"Soak the noodles in warm water for 10 minutes until pliable. Drop into a pot of boiling water for 1 minute, drain, rinse under cold water and snip into shorter lengths with scissors."},{"text":"Put the pork mince and water in a small frying pan over medium heat. Cook for 4 to 5 minutes, breaking it up, until no pink remains and it's cooked through."},{"text":"Add the prawns to the pan and cook for 2 minutes, until pink and opaque."},{"text":"Stir the dressing ingredients together in a large bowl until the sugar dissolves. Add the noodles, warm pork and prawns, shallots, celery and tomatoes and toss well."},{"text":"Toss through the spring onions and coriander, scatter with peanuts and serve on lettuce leaves."}],"notes":["The warm pork and prawns help the noodles soak up the dressing. Taste and adjust: it should be sour first, then salty, hot and only a little sweet.","Chinese celery, from Asian grocers, is more authentic; use the leaves too.","Food safety: Cook mince and sausages until no pink remains and the centre reaches 75°C."],"source":"user","provenance":"ai-draft"}},{"slug":"khai-jiao","title":"Khai Jiao","cuisine":"thai","meal_types":["breakfast","lunch"],"diets":["pescatarian","no-gluten","no-dairy"],"difficulty":"easy","total_minutes":15,"recipe":{"id":"khai-jiao","title":"Khai Jiao","summary":"The Thai omelette: eggs whisked frothy and fried in hot oil until puffed and crisp, served on rice with sriracha.","cuisine":"thai","diets":["pescatarian","no-gluten","no-dairy"],"mealTypes":["breakfast","lunch"],"difficulty":"easy","prepMinutes":5,"cookMinutes":10,"servings":2,"onePot":false,"ingredientGroups":[{"title":"Omelette","items":[{"item":"eggs","raw":"4 eggs","quantity":4,"ingredientId":"egg"},{"item":"fish sauce","raw":"2 tsp fish sauce","quantity":2,"unit":"tsp","ingredientId":"fish-sauce"},{"item":"lime juice","raw":"1 tsp lime juice","quantity":1,"unit":"tsp","ingredientId":"lime"},{"item":"rice flour","raw":"1 tbsp rice flour","quantity":1,"unit":"tbsp","ingredientId":"rice-flour"},{"item":"spring onion","raw":"1 spring onion, thinly sliced","quantity":1,"ingredientId":"spring-onion","prep":"thinly sliced"},{"item":"neutral oil","raw":"125ml neutral oil","quantity":125,"unit":"ml","ingredientId":"neutral-oil"}]},{"title":"To serve","items":[{"item":"cooked jasmine rice","raw":"300g cooked jasmine rice, hot","quantity":300,"unit":"g","ingredientId":"jasmine-rice","prep":"hot"},{"item":"Sriracha","raw":"Sriracha, to serve","ingredientId":"sriracha","prep":"to serve"},{"item":"Coriander leaves","raw":"Coriander leaves, to serve","ingredientId":"coriander","prep":"to serve"}]}],"steps":[{"text":"Whisk the eggs, fish sauce, lime juice and rice flour hard for 1 minute, until very frothy. Stir in the spring onion."},{"text":"Heat the oil in a wok over high heat until shimmering (about 180°C). A drop of egg should puff up immediately."},{"text":"Pour in half the egg from a little height, away from you. It will puff and bubble at once. Cook for about 1 minute, until crisp and golden underneath, then flip carefully and cook for 1 minute more."},{"text":"Lift out onto paper towel and repeat with the rest of the egg."},{"text":"Serve each omelette on a mound of hot rice with sriracha and coriander."}],"notes":["Hot oil spits when the egg goes in. Keep your face and hands back, and let the oil cool completely before moving the wok.","The omelette is cooked through, so it's fine for everyone."],"source":"user","provenance":"ai-draft"}},{"slug":"bun-cha","title":"Bun Cha","cuisine":"vietnamese","meal_types":["dinner","lunch"],"diets":["no-gluten","no-dairy"],"difficulty":"medium","total_minutes":75,"recipe":{"id":"bun-cha","title":"Bun Cha","summary":"Hanoi's chargrilled pork patties and pork belly in a warm, sweet-sour dipping broth, with noodles and herbs.","cuisine":"vietnamese","diets":["no-gluten","no-dairy"],"mealTypes":["dinner","lunch"],"difficulty":"medium","prepMinutes":50,"cookMinutes":25,"servings":4,"onePot":false,"seasons":["spring","summer"],"ingredientGroups":[{"title":"Pork","items":[{"item":"pork mince","raw":"500g pork mince","quantity":500,"unit":"g","ingredientId":"pork-mince"},{"item":"pork belly","raw":"400g pork belly, rind removed, thinly sliced","quantity":400,"unit":"g","ingredientId":"pork-belly","prep":"rind removed, thinly sliced"},{"item":"red shallots","raw":"3 red shallots, finely chopped","quantity":3,"ingredientId":"shallot","prep":"finely chopped"},{"item":"garlic","raw":"3 garlic cloves, crushed","quantity":3,"unit":"clove","ingredientId":"garlic","prep":"crushed"},{"item":"fish sauce","raw":"2 tbsp fish sauce","quantity":2,"unit":"tbsp","ingredientId":"fish-sauce"},{"item":"brown sugar","raw":"2 tbsp brown sugar","quantity":2,"unit":"tbsp","ingredientId":"brown-sugar"},{"item":"black pepper","raw":"1/2 tsp black pepper","quantity":0.5,"unit":"tsp","ingredientId":"black-pepper"},{"item":"neutral oil","raw":"1 tbsp neutral oil","quantity":1,"unit":"tbsp","ingredientId":"neutral-oil"}]},{"title":"Dipping broth","items":[{"item":"fish sauce","raw":"4 tbsp fish sauce","quantity":4,"unit":"tbsp","ingredientId":"fish-sauce"},{"item":"white sugar","raw":"3 tbsp white sugar","quantity":3,"unit":"tbsp","ingredientId":"sugar"},{"item":"limes","raw":"Juice of 2 limes","quantity":2,"ingredientId":"lime","prep":"juiced"},{"item":"warm water","raw":"375ml warm water","quantity":375,"unit":"ml","ingredientId":"water"},{"item":"garlic","raw":"2 garlic cloves, finely chopped","quantity":2,"unit":"clove","ingredientId":"garlic","prep":"finely chopped"},{"item":"bird's eye chilli","raw":"1 bird's eye chilli, sliced","quantity":1,"ingredientId":"birds-eye-chilli","prep":"sliced"},{"item":"carrot","raw":"1 carrot, thinly sliced","quantity":1,"ingredientId":"carrot","prep":"thinly sliced"}]},{"title":"To serve","items":[{"item":"rice vermicelli","raw":"300g rice vermicelli","quantity":300,"unit":"g","ingredientId":"rice-vermicelli"},{"item":"butter lettuce","raw":"1 butter lettuce, leaves separated","quantity":1,"ingredientId":"lettuce","prep":"leaves separated"},{"item":"mint leaves","raw":"Handful of mint leaves","quantity":1,"unit":"handful","ingredientId":"mint"},{"item":"Vietnamese mint","raw":"Handful of Vietnamese mint","quantity":1,"unit":"handful","ingredientId":"vietnamese-mint"},{"item":"coriander leaves","raw":"Handful of coriander leaves","quantity":1,"unit":"handful","ingredientId":"coriander"},{"item":"bean sprouts","raw":"100g bean sprouts","quantity":100,"unit":"g","ingredientId":"bean-sprouts"}]}],"steps":[{"text":"Mix the shallots, garlic, fish sauce, sugar, pepper and oil. Put half in a bowl with the pork mince and half with the pork belly. Mix each well, cover and refrigerate for 30 minutes."},{"text":"Stir the dipping broth ingredients together until the sugar dissolves."},{"text":"Cook the noodles according to the packet until tender, then rinse under cold water and drain well."},{"text":"Shape the mince into 16 small, flat patties. Heat a barbecue, chargrill pan or overhead grill to high. Cook the patties for 4 to 5 minutes a side, until charred and cooked through (75°C in the centre). Cook the belly slices for 2 to 3 minutes a side, until caramelised and cooked through."},{"text":"Divide the warm broth between four bowls and drop in the hot pork. Serve with the noodles, lettuce, herbs and bean sprouts, so everyone can dip noodles and greens into their broth."}],"notes":["Grilling over charcoal gives the real Hanoi smokiness, but a very hot chargrill pan does a good job.","Ask the butcher to slice the belly thinly, or freeze it for 30 minutes and slice it yourself.","Food safety: Cook mince, sausages, meatballs and liver right through to 75°C, with no pink in the centre."],"source":"user","provenance":"ai-draft"}},{"slug":"banh-xeo","title":"Banh Xeo","cuisine":"vietnamese","meal_types":["dinner"],"diets":["no-gluten","no-dairy"],"difficulty":"medium","total_minutes":90,"recipe":{"id":"banh-xeo","title":"Banh Xeo","summary":"Crisp Vietnamese turmeric and coconut pancakes filled with pork, prawns and bean sprouts, wrapped in lettuce and herbs.","cuisine":"vietnamese","diets":["no-gluten","no-dairy"],"mealTypes":["dinner"],"difficulty":"medium","prepMinutes":45,"cookMinutes":45,"servings":4,"onePot":false,"ingredientGroups":[{"title":"Batter","items":[{"item":"rice flour","raw":"200g rice flour","quantity":200,"unit":"g","ingredientId":"rice-flour"},{"item":"ground turmeric","raw":"1 tsp ground turmeric","quantity":1,"unit":"tsp","ingredientId":"ground-turmeric"},{"item":"salt","raw":"1/2 tsp salt","quantity":0.5,"unit":"tsp","ingredientId":"salt"},{"item":"coconut milk","raw":"270ml coconut milk","quantity":270,"unit":"ml","ingredientId":"coconut-milk"},{"item":"cold soda water","raw":"330ml cold soda water","quantity":330,"unit":"ml","ingredientId":"soda-water"},{"item":"spring onions","raw":"3 spring onions, thinly sliced","quantity":3,"ingredientId":"spring-onion","prep":"thinly sliced"}]},{"title":"Filling","items":[{"item":"pork belly","raw":"300g pork belly, rind removed, thinly sliced","quantity":300,"unit":"g","ingredientId":"pork-belly","prep":"rind removed, thinly sliced"},{"item":"raw prawns","raw":"300g raw prawns, peeled and deveined","quantity":300,"unit":"g","ingredientId":"prawn","prep":"peeled and deveined"},{"item":"brown onion","raw":"1 brown onion, thinly sliced","quantity":1,"ingredientId":"brown-onion","prep":"thinly sliced"},{"item":"bean sprouts","raw":"200g bean sprouts","quantity":200,"unit":"g","ingredientId":"bean-sprouts"},{"item":"neutral oil","raw":"4 tbsp neutral oil","quantity":4,"unit":"tbsp","ingredientId":"neutral-oil"}]},{"title":"Dipping sauce","items":[{"item":"fish sauce","raw":"3 tbsp fish sauce","quantity":3,"unit":"tbsp","ingredientId":"fish-sauce"},{"item":"white sugar","raw":"2 tbsp white sugar","quantity":2,"unit":"tbsp","ingredientId":"sugar"},{"item":"lime","raw":"Juice of 1 lime","quantity":1,"ingredientId":"lime","prep":"juiced"},{"item":"warm water","raw":"125ml warm water","quantity":125,"unit":"ml","ingredientId":"water"},{"item":"garlic","raw":"1 garlic clove, finely chopped","quantity":1,"unit":"clove","ingredientId":"garlic","prep":"finely chopped"},{"item":"bird's eye chilli","raw":"1 bird's eye chilli, sliced","quantity":1,"ingredientId":"birds-eye-chilli","prep":"sliced"}]},{"title":"To serve","items":[{"item":"butter lettuce","raw":"1 butter lettuce, leaves separated","quantity":1,"ingredientId":"lettuce","prep":"leaves separated"},{"item":"mint leaves","raw":"Handful of mint leaves","quantity":1,"unit":"handful","ingredientId":"mint"},{"item":"Thai basil leaves","raw":"Handful of Thai basil leaves","quantity":1,"unit":"handful","ingredientId":"thai-basil"}]}],"steps":[{"text":"Whisk the rice flour, turmeric, salt, coconut milk and soda water to a thin batter, like pouring cream. Stir in the spring onions and rest for 30 minutes."},{"text":"Stir the dipping sauce ingredients together until the sugar dissolves."},{"text":"Heat 1 tsp oil in a 24cm non-stick frying pan over high heat. Add an eighth of the pork and a few onion slices and fry for 2 minutes, until the pork is cooked through. Add an eighth of the prawns."},{"text":"Stir the batter, then pour in about 80ml and swirl the pan so it coats the base thinly. Cover and cook for 2 minutes. Scatter a handful of bean sprouts over one half, uncover and cook for 3 to 4 minutes more, until the edges are lacy and the base is golden and crisp. The prawns should be pink and opaque."},{"text":"Fold in half and slide onto a plate. Repeat with the rest, stirring the batter each time and keeping cooked ones warm in a low oven."},{"text":"To eat, break off pieces of pancake, wrap in lettuce with herbs and dip in the sauce."}],"notes":["A hot pan and a thin layer of batter are what make it crisp. The first one is often a tester.","Use any combination of pork, prawns or mushrooms for the filling.","Food safety: Cook fresh pork to at least 70°C in the thickest part."],"source":"user","provenance":"ai-draft"}},{"slug":"ga-kho-gung","title":"Caramelised Ginger Chicken","cuisine":"vietnamese","meal_types":["dinner"],"diets":["no-gluten","no-dairy"],"difficulty":"easy","total_minutes":55,"recipe":{"id":"ga-kho-gung","title":"Caramelised Ginger Chicken","summary":"Vietnamese ga kho gung: chicken thigh cooked down in a dark caramel with plenty of ginger and fish sauce.","cuisine":"vietnamese","diets":["no-gluten","no-dairy"],"mealTypes":["dinner"],"difficulty":"easy","prepMinutes":25,"cookMinutes":30,"servings":4,"onePot":false,"ingredientGroups":[{"title":"Chicken","items":[{"item":"chicken thigh fillets","raw":"800g chicken thigh fillets, cut into 4cm pieces","quantity":800,"unit":"g","ingredientId":"chicken-thigh","prep":"cut into 4cm pieces"},{"item":"fish sauce","raw":"2 tbsp fish sauce","quantity":2,"unit":"tbsp","ingredientId":"fish-sauce"},{"item":"black pepper","raw":"1 tsp black pepper","quantity":1,"unit":"tsp","ingredientId":"black-pepper"},{"item":"garlic","raw":"3 garlic cloves, finely chopped","quantity":3,"unit":"clove","ingredientId":"garlic","prep":"finely chopped"},{"item":"white sugar","raw":"3 tbsp white sugar","quantity":3,"unit":"tbsp","ingredientId":"sugar"},{"item":"neutral oil","raw":"2 tbsp neutral oil","quantity":2,"unit":"tbsp","ingredientId":"neutral-oil"},{"item":"ginger","raw":"50g ginger, peeled and cut into fine matchsticks","quantity":50,"unit":"g","ingredientId":"ginger","prep":"peeled and cut into fine matchsticks"},{"item":"red shallots","raw":"2 red shallots, sliced","quantity":2,"ingredientId":"shallot","prep":"sliced"},{"item":"water","raw":"125ml water","quantity":125,"unit":"ml","ingredientId":"water"}]},{"title":"To serve","items":[{"item":"spring onions","raw":"2 spring onions, sliced","quantity":2,"ingredientId":"spring-onion","prep":"sliced"},{"item":"long red chilli","raw":"1 long red chilli, sliced","quantity":1,"ingredientId":"red-chilli","prep":"sliced"},{"item":"jasmine rice","raw":"300g jasmine rice","quantity":300,"unit":"g","ingredientId":"jasmine-rice"}]}],"steps":[{"text":"Mix the chicken with the fish sauce, pepper and half the garlic and leave for 15 minutes. Start the rice."},{"text":"Put the sugar in a large frying pan or wide saucepan over medium heat. Leave it to melt without stirring, swirling the pan now and then, for 4 to 5 minutes until it's a deep amber caramel."},{"text":"Carefully add the oil, ginger, shallots and remaining garlic (the caramel will spit) and stir for 1 minute."},{"text":"Add the chicken and its marinade and toss for 3 minutes to coat. Pour in the water and simmer uncovered for 15 to 20 minutes, stirring now and then, until the sauce is sticky and dark and the chicken is cooked through (75°C)."},{"text":"Scatter with spring onion and chilli and serve with the rice."}],"notes":["Hot caramel burns badly. Keep children away from the stove and add the oil and aromatics at arm's length.","Take the caramel as dark as you dare without it smelling burnt; that bitterness is what balances the sweetness.","Food safety: Cook chicken (and other poultry) until the thickest part reaches 75°C and the juices run clear, with no pink meat near the bone."],"source":"user","provenance":"ai-draft"}},{"slug":"goi-ga","title":"Vietnamese Chicken Salad","cuisine":"vietnamese","meal_types":["lunch","dinner"],"diets":["no-gluten","no-dairy"],"difficulty":"easy","total_minutes":45,"recipe":{"id":"goi-ga","title":"Vietnamese Chicken Salad","summary":"Poached chicken, crunchy cabbage and lots of herbs in a sharp lime dressing, with peanuts and fried shallots.","cuisine":"vietnamese","diets":["no-gluten","no-dairy"],"mealTypes":["lunch","dinner"],"difficulty":"easy","prepMinutes":20,"cookMinutes":25,"servings":4,"onePot":false,"seasons":["spring","summer"],"ingredientGroups":[{"title":"Salad","items":[{"item":"chicken breast fillets","raw":"600g chicken breast fillets","quantity":600,"unit":"g","ingredientId":"chicken-breast"},{"item":"salt","raw":"1 tsp salt","quantity":1,"unit":"tsp","ingredientId":"salt"},{"item":"red onion","raw":"1/2 red onion, very thinly sliced","quantity":0.5,"ingredientId":"red-onion","prep":"very thinly sliced"},{"item":"white vinegar","raw":"1 tbsp white vinegar","quantity":1,"unit":"tbsp","ingredientId":"white-vinegar"},{"item":"wombok","raw":"1/4 wombok, finely shredded","quantity":0.25,"ingredientId":"wombok","prep":"finely shredded"},{"item":"carrot","raw":"1 carrot, cut into fine matchsticks","quantity":1,"ingredientId":"carrot","prep":"cut into fine matchsticks"},{"item":"Vietnamese mint","raw":"Large handful of Vietnamese mint","quantity":1,"unit":"handful","ingredientId":"vietnamese-mint","note":"large handful"},{"item":"mint leaves","raw":"Handful of mint leaves","quantity":1,"unit":"handful","ingredientId":"mint"},{"item":"coriander leaves","raw":"Handful of coriander leaves","quantity":1,"unit":"handful","ingredientId":"coriander"},{"item":"roasted peanuts","raw":"3 tbsp roasted peanuts, chopped","quantity":3,"unit":"tbsp","ingredientId":"peanuts","prep":"chopped"},{"item":"fried shallots","raw":"2 tbsp fried shallots","quantity":2,"unit":"tbsp","ingredientId":"fried-shallots"}]},{"title":"Dressing","items":[{"item":"fish sauce","raw":"3 tbsp fish sauce","quantity":3,"unit":"tbsp","ingredientId":"fish-sauce"},{"item":"limes","raw":"Juice of 2 limes","quantity":2,"ingredientId":"lime","prep":"juiced"},{"item":"white sugar","raw":"2 tbsp white sugar","quantity":2,"unit":"tbsp","ingredientId":"sugar"},{"item":"warm water","raw":"2 tbsp warm water","quantity":2,"unit":"tbsp","ingredientId":"water"},{"item":"garlic","raw":"1 garlic clove, finely chopped","quantity":1,"unit":"clove","ingredientId":"garlic","prep":"finely chopped"},{"item":"bird's eye chilli","raw":"1 bird's eye chilli, finely chopped","quantity":1,"ingredientId":"birds-eye-chilli","prep":"finely chopped"}]}],"steps":[{"text":"Put the chicken in a saucepan, cover with cold water and add the salt. Bring to a bare simmer, cook for 10 minutes, then turn off the heat, cover and leave for 15 minutes, until cooked through (75°C in the thickest part). Lift out and cool, then shred."},{"text":"Meanwhile, toss the red onion with the vinegar and leave for 10 minutes to soften its bite. Drain."},{"text":"Stir the dressing ingredients together until the sugar dissolves."},{"text":"Toss the chicken, onion, wombok, carrot and herbs with the dressing."},{"text":"Pile onto a platter and scatter with the peanuts and fried shallots."}],"notes":["Dress it just before serving so the cabbage stays crunchy.","A shredded barbecue chicken makes this a 15-minute lunch.","Food safety: Cook chicken (and other poultry) until the thickest part reaches 75°C and the juices run clear, with no pink meat near the bone."],"source":"user","provenance":"ai-draft"}}]$q$::jsonb)), dn as (select r, row_number() over (partition by r->>'cuisine' order by r->>'slug') rn from d), cand as (select c.id, x.cuisine, row_number() over (partition by x.cuisine order by c.recipe_count, c.handle)-1 ix, count(*) over (partition by x.cuisine) cnt from public.cooks c join (select distinct cook_id, cuisine from public.published_recipes where status='published') x on x.cook_id=c.id where c.kind='person'), ins as (insert into public.published_recipes (cook_id,slug,title,cuisine,meal_types,diets,difficulty,total_minutes,recipe,review,status) select coalesce((select cd.id from cand cd where cd.cuisine=dn.r->>'cuisine' and cd.ix=(dn.rn-1)%cd.cnt),(select id from public.cooks where kind='official' limit 1)), dn.r->>'slug', dn.r->>'title', dn.r->>'cuisine', array(select jsonb_array_elements_text(dn.r->'meal_types')), array(select jsonb_array_elements_text(dn.r->'diets')), dn.r->>'difficulty', (dn.r->>'total_minutes')::int, jsonb_set(dn.r->'recipe','{notes}',coalesce((select jsonb_agg(n) from jsonb_array_elements(dn.r->'recipe'->'notes') n where btrim(n#>>'{}') <> 'Food safety:'),'[]'::jsonb)), 'auto-checked','published' from dn where not exists (select 1 from public.published_recipes q where q.slug=dn.r->>'slug') on conflict do nothing returning id) select (select count(*) from d) expected, (select count(*) from ins) inserted;